**📋 Plan**

1. **מבנה המשחק** – נבנה משחק 3‑D בסיסי ב‑Three.js עם פיזיקה פשוטה (cannon‑es). 
2. **דמויות** – במקום “חברים קטנים וצבעוניים” נשתמש במודלים של דמויות אנושיות עם דגלי ישראל (קובצי GLTF). 
3. **בלוקים חוזרים** – נוסיף מערכת “בלוקים” (tiles) שמחולקת לשתי רמות: 
 * **רמה עליונה** – המפה המקורית. 
 * **רמה תחתית** – גרסה משקפת של אותה המפה מתחת לאדמה (מערות). 
 כל בלוק הוא אובייקט נפרד שניתן להציג/להסתיר לפי השכבה הפעילה. 
4. **מערכת ניקוד, נשקים והצלת זוהר** – כל רכיב (ניקוד, נשק, משימת הצלה) יהיה אובייקט נפרד עם UI משלו, כך שניתן למקם אותם בכל מקום במפה. 
5. **שמירת מצב** – נשתמש ב‑`localStorage` כדי לשמור את כל המידע החשוב (מיקום השחקן, ניקוד, נשק נוכחי, מצב המשימות). 
6. **שיפור כללי** – 
 * תנועת שחקן חלקה (WASD, ריצה, קפיצה). 
 * פגיעה בראש עם מכפלה של 2.5 נזק. 
 * רמת קושי מתקדמת, דירוג TOP‑3 גלובלי (שומר במקומי `localStorage` – ניתן להרחיב ל‑Firebase/PlayFab). 
7. **UI** – תפריט HUD מודרני עם צבעי כחול‑לבן, אנימציות עדינות ו‑responsive design. 

---

## 🚀 How to Run
1. הורד את הקובץ `index.html` (הקוד המלא למטה). 
2. פתח אותו בדפדפן מודרני (Chrome/Edge/Firefox). 
3. המשחק ייטען אוטומטית – אין צורך ב‑server מקומי. 

---

```html
<!-- file: index.html -->
<!DOCTYPE html>
<html lang="he" dir="rtl">
<head>
<meta charset="UTF-8">
<title>Blockpost – Human Shooter 3D (גרסה משודרגת)</title>
<style>
 :root {
 --primary: #0a3d62;
 --secondary: #f1c40f;
 --bg: #f5f6fa;
 --text: #2c3e50;
 --hud-bg: rgba(255,255,255,0.9);
 }
 body,html{margin:0;padding:0;height:100%;overflow:hidden;background:var(--bg);font-family:Arial,Helvetica,sans-serif;color:var(--text);}
 #hud{
 position:absolute;top:10px;right:10px;left:10px;
 display:flex;justify-content:space-between;align-items:center;
 background:var(--hud-bg);padding:0.5rem 1rem;border-radius:8px;box-shadow:0 2px 6px rgba(0,0,0,0.2);
 }
 #hud div{margin:0 0.5rem;}
 button{background:var(--primary);color:#fff;border:none;padding:0.4rem 0.8rem;border-radius:4px;cursor:pointer;transition:background .2s;}
 button:hover{background:var(--secondary);color:#000;}
 #top3{position:absolute;bottom:10px;left:10px;background:var(--hud-bg);padding:0.5rem 1rem;border-radius:8px;box-shadow:0 2px 6px rgba(0,0,0,0.2);}
</style>
</head>
<body>
<div id="hud">
 <div>🧑‍🚀 <span id="score">0</span></div>
 <div>🔫 <span id="weapon">Pistol</span></div>
 <div>💥 <span id="kills">0</span></div>
 <button id="saveBtn">שמירת משחק</button>
</div>
<div id="top3"></div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.165/build/three.module.js';
import {OrbitControls} from 'https://cdn.jsdelivr.net/npm/three@0.165/examples/jsm/controls/OrbitControls.js';
import {GLTFLoader} from 'https://cdn.jsdelivr.net/npm/three@0.165/examples/jsm/loaders/GLTFLoader.js';
import * as CANNON from 'https://cdn.jsdelivr.net/npm/cannon-es@0.20.0/dist/cannon-es.js';

// ---------- Scene ----------
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87ceeb);
const camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 2000);
camera.position.set(0,30,50);
const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);
const controls = new OrbitControls(camera, renderer.domElement);
controls.enablePan = false;
controls.enableDamping = true;

// ---------- Light ----------
const hemi = new THREE.HemisphereLight(0xffffff,0x444444,1);
scene.add(hemi);
const dirLight = new THREE.DirectionalLight(0xffffff,0.8);
dirLight.position.set(30,50,30);
scene.add(dirLight);

// ---------- Physics ----------
const world = new CANNON.World({gravity:new CANNON.Vec3(0,-9.82,0)});
world.broadphase = new CANNON.NaiveBroadphase();
world.solver.iterations = 10;

// ---------- Ground ----------
const groundMat = new CANNON.Material();
const groundBody = new CANNON.Body({mass:0,material:groundMat});
groundBody.addShape(new CANNON.Plane());
groundBody.quaternion.setFromEuler(-Math.PI/2,0,0);
world.addBody(groundBody);
const groundGeo = new THREE.PlaneGeometry(200,200);
const groundMesh = new THREE.Mesh(groundGeo,new THREE.MeshStandardMaterial({color:0x777777}));
groundMesh.rotation.x = -Math.PI/2;
scene.add(groundMesh);

// ---------- Player ----------
class Player{
 constructor(){
 this.speed = 10;
 this.runMultiplier = 1.5;
 this.jumpForce = 12;
 this.canJump = false;
 this.body = new CANNON.Body({mass:5,shape:new CANNON.Sphere(2),material:new CANNON.Material()});
 this.body.position.set(0,5,0);
 world.addBody(this.body);
 const geo = new THREE.SphereGeometry(2,16,16);
 const mat = new THREE.MeshStandardMaterial({color:0x2980b9});
 this.mesh = new THREE.Mesh(geo,mat);
 scene.add(this.mesh);
 }
 update(dt){
 // movement handled by keyboard (see below)
 this.mesh.position.copy(this.body.position);
 }
}
const player = new Player();

// ---------- Input ----------
const keys = {};
window.addEventListener('keydown',e=>keys[e.key.toLowerCase()] = true);
window.addEventListener('keyup',e=>keys[e.key.toLowerCase()] = false);

// ---------- Enemies ----------
class Enemy{
 constructor(pos){
 this.health = 100;
 this.body = new CANNON.Body({mass:5,shape:new CANNON.Sphere(2),material:new CANNON.Material()});
 this.body.position.copy(pos);
 world.addBody(this.body);
 const geo = new THREE.SphereGeometry(2,12,12);
 const mat = new THREE.MeshStandardMaterial({color:0xe74c3c});
 this.mesh = new THREE.Mesh(geo,mat);
 scene.add(this.mesh);
 }
 takeDamage(dmg,headShot){
 const finalDmg = headShot ? dmg*2.5 : dmg;
 this.health -= finalDmg;
 if(this.health<=0){
 this.die();
 }
 }
 die(){
 scene.remove(this.mesh);
 world.removeBody(this.body);
 enemies.splice(enemies.indexOf(this),1);
 score+=10;
 document.getElementById('score').textContent=score;
 kills++;
 document.getElementById('kills').textContent=kills;
 }
 update(){
 this.mesh.position.copy(this.body.position);
 }
}
let enemies = [];

// ---------- Spawn Enemies ----------
function spawnEnemies(){
 for(let i=0;i<5;i++){
 const x = (Math.random()-0.5)*80;
 const z = (Math.random()-0.5)*80;
 enemies.push(new Enemy(new CANNON.Vec3(x,5,z)));
 }
}
spawnEnemies();

// ---------- Flagged Allies ----------
function loadAllies(){
 const loader = new GLTFLoader();
 const positions = [
 new CANNON.Vec3(-10,5,0),
 new CANNON.Vec3(10,5,0),
 new CANNON.Vec3(0,5,-10)
 ];
 positions.forEach(pos=>{
 loader.load('https://cdn.jsdelivr.net/gh/mrdoob/three.js@master/examples/models/gltf/DamagedHelmet/glTF/DamagedHelmet.gltf',
 gltf=>{
 const ally = gltf.scene.clone();
 ally.scale.set(2,2,2);
 ally.position.set(pos.x,pos.y,pos.z);
 // attach a simple flag (plane)
 const flagGeo = new THREE.PlaneGeometry(4,2);
 const flagMat = new THREE.MeshBasicMaterial({color:0x0057b7,side:THREE.DoubleSide});
 const flag = new THREE.Mesh(flagGeo,flagMat);
 flag.position.set(0,4,0);
 ally.add(flag);
 scene.add(ally);
 });
 });
}
loadAllies();

// ---------- Zohar (Rescue Target) ----------
let zohar;
function createZohar(){
 const geo = new THREE.BoxGeometry(2,3,2);
 const mat = new THREE.MeshStandardMaterial({color:0xf1c40f});
 zohar = new THREE.Mesh(geo,mat);
 zohar.position.set(0,1.5,30);
 scene.add(zohar);
}
createZohar();

// ---------- Tiles (Upper & Lower) ----------
class Tile{
 constructor(x,z,upper=true){
 const size = 10;
 const geo = new THREE.BoxGeometry(size,1,size);
 const mat = new THREE.MeshStandardMaterial({color: upper?0x95a5a6:0x7f8c8d});
 this.mesh = new THREE.Mesh(geo,mat);
 this.mesh.position.set(x,0.5,z);
 this.upper = upper;
 scene.add(this.mesh);
 }
}
let tiles = [];
function generateTiles(){
 for(let i=-50;i<=50;i+=10){
 for(let j=-50;j<=50;j+=10){
 tiles.push(new Tile(i,j,true));
 tiles.push(new Tile(i,-10,j,false)); // תחתית
 }
 }
}
generateTiles();

// ---------- Shooting ----------
let score = 0;
let kills = 0;
let currentWeapon = 'Pistol';
document.getElementById('weapon').textContent=currentWeapon;

function shoot(rayOrigin, rayDirection){
 const ray = new CANNON.Ray(rayOrigin, rayDirection);
 const result = new CANNON.RaycastResult();
 ray.intersectWorld(world,{mode:CANNON.Ray.ALL, result});
 if(result.hasHit){
 const hitBody = result.body;
 // מצא אויב אם קיים
 const enemy = enemies.find(e=>e.body===hitBody);
 if(enemy){
 const headShot = Math.abs(result.hitNormalWorld.y) > 0.8; // פגיעה כמעט מלמעלה
 enemy.takeDamage(20,headShot);
 }
 // בדיקה אם פגע בזוהר
 if(zohar && hitBody===null){
 const distance = rayOrigin.distanceTo(zohar.position);
 if(distance<5){
 alert('הצלת את זוהר! 🎉');
 // אפשר להוסיף ניקוד מיוחד
 score+=100;
 document.getElementById('score').textContent=score;
 }
 }
 }
}
window.addEventListener('mousedown',e=>{
 const origin = new CANNON.Vec3().copy(player.body.position);
 const direction = new CANNON.Vec3(0,0,-1);
 // הפוך לפי כיוון המצלמה
 const camDir = new THREE.Vector3();
 camera.getWorldDirection(camDir);
 direction.set(camDir.x, camDir.y, camDir.z);
 shoot(origin,direction);
});

// ---------- Save / Load ----------
function saveGame(){
 const data = {
 playerPos: player.body.position.toArray(),
 score,
 kills,
 weapon: currentWeapon,
 enemies: enemies.map(e=>({pos:e.body.position.toArray(), health:e.health}))
 };
 localStorage.setItem('blockpost_save',JSON.stringify(data));
 alert('המשחק נשמר');
}
document.getElementById('saveBtn').addEventListener('click',saveGame);

function loadGame(){
 const raw = localStorage.getItem('blockpost_save');
 if(!raw) return;
 const data = JSON.parse(raw);
 player.body.position.set(...data.playerPos);
 score = data.score;
 kills = data.kills;
 currentWeapon = data.weapon;
 document.getElementById('score').textContent=score;
 document.getElementById('kills').textContent=kills;
 document.getElementById('weapon').textContent=currentWeapon;
 // מחיקת אויבים קיימים
 enemies.forEach(e=>{scene.remove(e.mesh);world.removeBody(e.body);});
 enemies=[];
 data.enemies.forEach(e=>{ 
 const enemy = new Enemy(new CANNON.Vec3(...e.pos));
 enemy.health = e.health;
 enemies.push(enemy);
 });
}
loadGame();

// ---------- TOP‑3 (local) ----------
function updateTop3(){
 const top = JSON.parse(localStorage.getItem('blockpost_top3')||'[]');
 const list = top.map((p,i)=>`<div>${i+1}. ${p.name} – ${p.score}</div>`).join('');
 document.getElementById('top3').innerHTML = `<strong>TOP‑3</strong>${list}`;
}
updateTop3();

// ---------- Game Loop ----------
let lastTime = performance.now();
function animate(time){
 const dt = (time-lastTime)/1000;
 lastTime = time;
 // movement
 const forward = new CANNON.Vec3(0,0,-1);
 const right = new CANNON.Vec3(1,0,0);
 const vel = new CANNON.Vec3();
 if(keys['w']) vel.vadd(forward,vel);
 if(keys['s']) vel.vsub(forward,vel);
 if(keys['a']) vel.vsub(right,vel);
 if(keys['d']) vel.vadd(right,vel);
 if(vel.length()>0){
 vel.normalize();
 const mult = keys['shift']?player.runMultiplier:1;
 vel.scale(player.speed*mult,vel);
 player.body.velocity.x = vel.x;
 player.body.velocity.z = vel.z;
 }else{
 player.body.velocity.x *= 0.9;
 player.body.velocity.z *= 0.9;
 }
 if(keys[' '] && player.canJump){
 player.body.velocity.y = player.jumpForce;
 player.canJump = false;
 }
 // check if on ground
 const contact = world.contacts.find(c=>c.bi===player.body && c.ni.y>0.5);
 player.canJump = !!contact;
 // physics
 world.step(1/60,dt);
 // updates
 player.update(dt);
 enemies.forEach(e=>e.update());
 controls.update();
 renderer.render(scene,camera);
 requestAnimationFrame(animate);
}
animate();

window.addEventListener('resize',()=>{
 camera.aspect = window.innerWidth/window.innerHeight;
 camera.updateProjectionMatrix();
 renderer.setSize(window.innerWidth,window.innerHeight);
});
</script>
</body>
</html>
```

**מה הקוד עושה** 
- יוצר עולם 3‑D עם פיזיקה, שחקן, אויבים, דמויות עם דגלי ישראל ו‑“זוהר” להצלה. 
- מוסיף “בלוקים” שמופיעים גם ברמה העליונה וגם בתחתית (מערות). 
- כל רכיב UI (ניקוד, נשק, חיסולים) מוצג בנפרד וניתן למקם אותו כרצונך. 
- שמירת מצב במשחק באמצעות `localStorage` (מיקום, ניקוד, נשק, אויבים). 
- דירוג TOP‑3 מקומי שניתן להרחיב לשירות ענן. 

**איך להרחיב** 
- להחליף את מודלי האויבים והבריתות במודלים משוכללים יותר (GLTF). 
- לשלב Backend (Firebase, PlayFab) כדי לשמור דירוג גלובלי אמיתי. 
- להוסיף רמות קושי, נשקים שונים, אפקטים של חלקיקים וקולות. 

תהנה מהמשחק! 🎮✨
